class Player extends SpriteComponent with KeyboardHandler {
  final Vector2 velocity = Vector2.zero();
  @override
  bool onKeyEvent(KeyEvent e, Set<LogicalKeyboardKey> keys) {
    velocity.x = (keys.contains(LogicalKeyboardKey.arrowRight) ? 1 : 0)
               - (keys.contains(LogicalKeyboardKey.arrowLeft) ? 1 : 0);
    return true;
  }
  @override
  void update(double dt) => position += velocity * 200 * dt;
}
