extends VehicleBody3D
@export var max_engine := 220.0
@export var max_steer := 0.45
func _physics_process(delta):
    var speed := linear_velocity.length()
    # فرمان حساس به سرعت: در سرعت بالا کمتر می‌چرخد
    var steer_limit := lerp(max_steer, 0.12, clamp(speed / 30.0, 0.0, 1.0))
    var target := Input.get_axis("right", "left") * steer_limit
    steering = move_toward(steering, target, 2.5 * delta)   # برگشت خودکار فرمان
    engine_force = Input.get_axis("brake", "accelerate") * max_engine
    brake = 30.0 if Input.is_action_pressed("handbrake") else 0.0
    if Input.is_action_pressed("handbrake"):
        $RearLeft.wheel_friction_slip = 1.2   # دریفت
        $RearRight.wheel_friction_slip = 1.2
    else:
        $RearLeft.wheel_friction_slip = 2.8
        $RearRight.wheel_friction_slip = 2.8

func enter_car():
    $DriveCam.priority = 20
    $WalkCam.priority = 0

